-- +goose StatementBegin

-- Shared helpers used by every module's schema.
--
-- Conventions (see docs/adr/0003-database-conventions.md):
--   * Primary keys are UUIDv7 generated by PostgreSQL 18's native uuidv7()
--     (time-ordered => index friendly). Clients that must create rows while
--     offline may supply their own UUIDv7.
--   * Money            => NUMERIC(18,2)
--   * Quantity / cost  => NUMERIC(18,4)
--   * Never FLOAT/REAL for money or stock.
--   * Every timestamp is TIMESTAMPTZ (stored in UTC).

-- Keeps updated_at truthful without relying on application code.
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

-- Makes a table append-only (used for audit_logs and, later, stock_ledgers).
CREATE FUNCTION forbid_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% on table % is not allowed: table is append-only', TG_OP, TG_TABLE_NAME
        USING ERRCODE = 'restrict_violation';
END;
$$;

-- +goose StatementEnd

-- +goose Down
DROP FUNCTION IF EXISTS forbid_mutation();
DROP FUNCTION IF EXISTS set_updated_at();
